    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v, _ in counts.most_common() if v != bg)

    # Locate the connected, non-background, non-marker template.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg, marker) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] not in (bg, marker)):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(cells)

    template = max(components, key=len)
    rows = [r for r, c in template]
    cols = [c for r, c in template]

    if len(set(rows)) == 1:
        r0 = rows[0]
        pattern = [grid[r0][c] for c in sorted(cols)]
        axis = "horizontal"
    else:
        c0 = cols[0]
        pattern = [grid[r][c0] for r in sorted(rows)]
        axis = "vertical"

    out = [row[:] for row in grid]
    half = len(pattern) // 2
    for r in range(h):
        for c in range(w):
            if grid[r][c] != marker:
                continue
            for i, color in enumerate(pattern):
                if axis == "horizontal":
                    rr, cc = r, c + i - half
                else:
                    rr, cc = r + i - half, c
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = color
    return out
